# CONSISTENCY CHECK — no outstanding problems in the model.

function.arguments:
{"yaml":"actions:
  declareMajorIncident:
    input: Incident
    preconditions:
      - canDeclareMajorIncident
    effect: |
      set incident.majorIncidentDeclared to true and set incident.majorIncidentDeclaredAt to current time; 
      create a Notification targeting the Person record linked as IncidentCommander via incidentCommandedBy relationship with notificationType major-incident-declared; 
      create a Notification targeting the Person record linked as DutyManager via incidentManagedBy relationship with notificationType major-incident-declared
    verification: |
      read the incident and confirm majorIncidentDeclared is true and majorIncidentDeclaredAt is set; 
      confirm two Notification objects exist linked by incidentHasNotification and each targets the IncidentCommander and DutyManager Person records respectively
"}
